-- Ajoute la colonne logo_path a la table clients, sur tous les schemas -- tenant existants. Idempotent (IF NOT EXISTS). SET client_encoding TO 'UTF8';  DO $OUTER$ DECLARE   schema_rec RECORD; BEGIN   FOR schema_rec IN     SELECT schema_name FROM information_schema.schemata     WHERE schema_name NOT IN ('pg_catalog','information_schema','public')   LOOP     EXECUTE format('ALTER TABLE %I.clients ADD COLUMN IF NOT EXISTS logo_path TEXT', schema_rec.schema_name);     RAISE NOTICE 'OK : %.clients.logo_path', schema_rec.schema_name;   END LOOP; END $OUTER$;